CREATE TABLE IF NOT EXISTS recipes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, name TEXT NOT NULL, servings NUMERIC NOT NULL CHECK (servings > 0), serving_grams NUMERIC NOT NULL DEFAULT 100, calories NUMERIC NOT NULL DEFAULT 0, protein NUMERIC NOT NULL DEFAULT 0, carbs NUMERIC NOT NULL DEFAULT 0, fat NUMERIC NOT NULL DEFAULT 0, fiber NUMERIC NOT NULL DEFAULT 0, food_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());